/// Signs a person in with a name and password. The answer holds the session token the console sends from then on.
#[endpoint { method = POST, path = "/v1/login", tags = ["session"] }]
pub async fn login(
    rqctx: RequestContext<ApiContext>,
    body: TypedBody<LoginParams>,
) -> Result<HttpResponseOk<LoginResult>, HttpError> {
    let params = body.into_inner();
    let (user, session) = sessions::login(rqctx.context(), &params.user_name, &params.password)?;
    Ok(HttpResponseOk(LoginResult {
        token: session.token,
        user_name: user.name,
        expires_at: session.expires_at,
    }))
}

/// Signs out: ends the session whose token the request carries. It needs no valid session to succeed.
#[endpoint { method = POST, path = "/v1/logout", tags = ["session"] }]
pub async fn logout(rqctx: RequestContext<ApiContext>) -> Result<HttpResponseUpdatedNoContent, HttpError> {
    if let Some(token) = session_auth::bearer_token(&rqctx) {
        sessions::logout(rqctx.context(), &token);
    }
    Ok(HttpResponseUpdatedNoContent())
}

/// Signs a person in with their name and password, and starts a session.
/// An unknown name and a wrong password get the same answer.
pub fn login(ctx: &ApiContext, user_name: &str, password: &str) -> Result<(User, Session), ApiError> {
    let now = now_seconds();
    let mut db = ctx.datastore.lock();
    let user = db.user_by_name(user_name).ok_or(ApiError::InvalidCredentials)?;
    if let Some(until) = user.locked_until {
        if until > now {
            return Err(ApiError::AccountLocked { until });
        }
    }
    if user.password_digest != password_digest(user_name, password) {
        let failed = db.user_record_failed_login(&user.id);
        if failed >= MAX_FAILED_LOGINS {
            db.user_lock_until(&user.id, now + LOCK_SECONDS);
        }
        return Err(ApiError::InvalidCredentials);
    }
    db.user_clear_failed_logins(&user.id);
    let session = db.session_insert(&user.id, now + SESSION_SECONDS);
    Ok((user, session))
}

/// Ends the session a token belongs to. A token that is already gone is not an error.
pub fn logout(ctx: &ApiContext, token: &str) {
    ctx.datastore.lock().session_delete(token);
}

/// The session token a request carries in its `Authorization: Bearer` header.
pub fn bearer_token(rqctx: &RequestContext<ApiContext>) -> Option<String> {
    let header = rqctx.request.headers().get("authorization")?.to_str().ok()?;
    let token = header.strip_prefix("Bearer ")?.trim();
    if token.is_empty() {
        return None;
    }
    Some(token.to_string())
}

/// Says who is calling, from the session token the console sends. An expired session is deleted.
pub fn authenticate(rqctx: &RequestContext<ApiContext>) -> Result<User, ApiError> {
    let token = bearer_token(rqctx).ok_or(ApiError::Unauthenticated)?;
    let mut db = rqctx.context().datastore.lock();
    let session = db.session_by_token(&token).ok_or(ApiError::Unauthenticated)?;
    if session.expires_at <= now_seconds() {
        db.session_delete(&token);
        return Err(ApiError::SessionExpired);
    }
    db.user_by_id(&session.user_id).ok_or(ApiError::Unauthenticated)
}

/// Finds a project by name and checks the caller's role on it. A project the caller has no role on looks missing.
pub fn authorize_project(
    db: &Tables,
    caller: &User,
    project_name: &str,
    needed: ProjectRole,
) -> Result<(Project, ProjectRole), ApiError> {
    let project = db.project_by_name(project_name).ok_or(ApiError::ProjectNotFound)?;
    let role = require_role(db, caller, &project.id, needed)?;
    Ok((project, role))
}

/// Checks the caller's role on a project. No role at all reads as "not found", so names do not leak.
pub fn require_role(
    db: &Tables,
    caller: &User,
    project_id: &str,
    needed: ProjectRole,
) -> Result<ProjectRole, ApiError> {
    let role = db.role_of(project_id, &caller.id).ok_or(ApiError::ProjectNotFound)?;
    if role < needed {
        return Err(ApiError::Forbidden { needed });
    }
    Ok(role)
}

pub fn user_lock_until(&mut self, user_id: &str, until: u64) {
    if let Some(user) = self.users.iter_mut().find(|user| user.id == user_id) {
        user.failed_logins = 0;
        user.locked_until = Some(until);
    }
}

pub fn user_clear_failed_logins(&mut self, user_id: &str) {
    if let Some(user) = self.users.iter_mut().find(|user| user.id == user_id) {
        user.failed_logins = 0;
        user.locked_until = None;
    }
}

pub fn session_insert(&mut self, user_id: &str, expires_at: u64) -> Session {
    let session = Session {
        token: uuid::Uuid::new_v4().simple().to_string(),
        user_id: user_id.to_string(),
        expires_at,
    };
    self.sessions.push(session.clone());
    session
}

/// Gives a person a role on a project, replacing the role they had.
pub fn role_set(&mut self, project_id: &str, user_id: &str, role: ProjectRole) {
    self.role_assignments.retain(|each| !(each.project_id == project_id && each.user_id == user_id));
    self.role_assignments.push(RoleAssignment {
        project_id: project_id.to_string(),
        user_id: user_id.to_string(),
        role,
    });
}

/** The person submits the sign-in form. */
export async function sign_in(user_name: string, password: string): Promise<boolean> {
  if (user_name.trim() === "" || password === "") {
    show_message("Enter your name and password.");
    return false;
  }
  try {
    const result = await api_client.login(user_name.trim(), password);
    console_state.session_token = result.token;
    console_state.user_name = result.user_name;
    page.remember(SESSION_KEY, result.token);
    page.remember(USER_KEY, result.user_name);
  } catch (error) {
    show_message(message_for(error));
    return false;
  }
  show_message(null);
  await open_first_project();
  return true;
}

/** The console opens in a browser that signed in before. */
export async function restore_session(): Promise<void> {
  const token = page.recall(SESSION_KEY);
  if (token === null) {
    console_state.screen = "sign_in";
    return;
  }
  console_state.session_token = token;
  console_state.user_name = page.recall(USER_KEY);
  await open_first_project();
}

/** Loads the person's projects and opens the one they used last, or the first one. */
export async function open_first_project(): Promise<void> {
  try {
    console_state.projects = await api_client.project_list();
  } catch (error) {
    handle_refusal(error);
    return;
  }
  if (console_state.projects.length === 0) {
    console_state.current_project = null;
    console_state.screen = "no_projects";
    return;
  }
  const last_used = page.recall(LAST_PROJECT_KEY);
  const project = console_state.projects.find((each) => each.name === last_used) ?? console_state.projects[0];
  if (project !== undefined) {
    await switch_project(project.name);
  }
}

/** The person presses "Sign out". The console signs out even when the API cannot be told. */
export async function sign_out(): Promise<void> {
  try {
    await api_client.logout();
  } catch {
    // The session ends on its own after eight hours.
  }
  forget_session();
  show_message(null);
}

/** Shows why the API refused something. A refusal that means "signed out" returns the person to the sign-in form. */
export function handle_refusal(error: unknown): void {
  if (signed_out(error)) {
    forget_session();
    show_message("Your session ended. Sign in again.");
    return;
  }
  show_message(message_for(error));
}

/** What to tell the person when the API refuses something, in plain words with a next step. */
export function message_for(error: unknown): string {
  if (error instanceof ApiError) {
    return MESSAGES[error.error_code] ?? "Something went wrong. Try again.";
  }
  return "Something went wrong. Try again.";
}

/** The rule the API applies to names, checked in the form first so the person hears sooner. */
export function name_problem(name: string): string | null {
  if (name === "") {
    return "Enter a name.";
  }
  if (!NAME_PATTERN.test(name) || name.endsWith("-") || name.length > MAX_NAME_LENGTH) {
    return "Use lowercase letters, numbers and dashes, starting with a letter. 40 characters at most.";
  }
  return null;
}

/** The person picks a project in the project menu. */
export async function switch_project(project_name: string): Promise<boolean> {
  try {
    const [detail, instances, disks] = await Promise.all([
      api_client.project_view(project_name),
      api_client.instance_list(project_name),
      api_client.disk_list(project_name),
    ]);
    console_state.current_project = detail;
    console_state.instances = instances;
    console_state.disks = disks;
  } catch (error) {
    handle_refusal(error);
    return false;
  }
  console_state.screen = "project";
  page.remember(LAST_PROJECT_KEY, project_name);
  return true;
}

/** The person submits the new-project form. */
export async function submit_create_project(name: string, description: string): Promise<boolean> {
  const problem = name_problem(name);
  if (problem !== null) {
    show_message(problem);
    return false;
  }
  try {
    const project = await api_client.project_create(name, description.trim());
    console_state.projects = [...console_state.projects, project].sort((a, b) => a.name.localeCompare(b.name));
  } catch (error) {
    handle_refusal(error);
    return false;
  }
  show_message(null);
  return switch_project(name);
}

/** The person presses "Delete project" and confirms. */
export async function delete_project(project_name: string): Promise<boolean> {
  const current = console_state.current_project;
  if (current !== null && current.project.name === project_name) {
    if (current.role !== "admin") {
      show_message("Only a project admin can delete a project.");
      return false;
    }
    if (current.usage.instances > 0 || current.usage.disks > 0) {
      show_message(
        `This project still holds ${current.usage.instances} instances and ${current.usage.disks} disks. Delete them first.`,
      );
      return false;
    }
  }
  const confirmed = await page.confirm(`Delete the project "${project_name}"? This cannot be undone.`);
  if (!confirmed) {
    return false;
  }
  try {
    await api_client.project_delete(project_name);
  } catch (error) {
    handle_refusal(error);
    return false;
  }
  page.remember(LAST_PROJECT_KEY, null);
  show_message(`The project "${project_name}" was deleted.`);
  await open_first_project();
  return true;
}

/** A project admin gives someone a role from the access page. */
export async function give_role(user_name: string, role: ProjectRole): Promise<boolean> {
  const current = console_state.current_project;
  if (current === null) {
    return false;
  }
  if (user_name.trim() === "") {
    show_message("Enter the person's name.");
    return false;
  }
  try {
    await api_client.project_member_set(current.project.name, user_name.trim(), role);
  } catch (error) {
    handle_refusal(error);
    return false;
  }
  show_message(`${user_name.trim()} is now ${role} on ${current.project.name}.`);
  return true;
}

/** What is wrong with the create-instance form, or null. It also checks the project's remaining quota. */
export function instance_form_problem(form: InstanceCreateParams): string | null {
  const current = console_state.current_project;
  if (current === null) {
    return "Choose a project first.";
  }
  const problem = name_problem(form.name);
  if (problem !== null) {
    return problem;
  }
  if (!Number.isInteger(form.ncpus) || form.ncpus < 1 || form.ncpus > 8) {
    return "Choose 1 to 8 CPUs.";
  }
  if (!Number.isInteger(form.memory_gib) || form.memory_gib < 1 || form.memory_gib > 32) {
    return "Choose 1 to 32 GiB of memory.";
  }
  if (!Number.isInteger(form.boot_disk_size_gib) || form.boot_disk_size_gib < 10 || form.boot_disk_size_gib > 200) {
    return "Choose a boot disk of 10 to 200 GiB.";
  }
  const { project, usage } = current;
  if (form.ncpus > project.quota_cpus - usage.cpus) {
    return `This project has ${project.quota_cpus - usage.cpus} CPUs left. Choose fewer, or delete an instance.`;
  }
  if (form.memory_gib > project.quota_memory_gib - usage.memory_gib) {
    return `This project has ${project.quota_memory_gib - usage.memory_gib} GiB of memory left. Choose less.`;
  }
  if (form.boot_disk_size_gib > project.quota_disk_gib - usage.disk_gib) {
    return `This project has ${project.quota_disk_gib - usage.disk_gib} GiB of disk left. Choose a smaller disk.`;
  }
  return null;
}

/** The person submits the create-instance form. */
export async function submit_create_instance(form: InstanceCreateParams): Promise<Instance | null> {
  const problem = instance_form_problem(form);
  const current = console_state.current_project;
  if (problem !== null || current === null) {
    show_message(problem);
    return null;
  }
  let instance: Instance;
  try {
    instance = await api_client.instance_create(current.project.name, form);
  } catch (error) {
    handle_refusal(error);
    return null;
  }
  replace_instance(instance);
  show_message(`Creating ${instance.name}…`);
  const settled = await wait_for_instance(instance.id, ["running", "failed"]);
  await switch_project(current.project.name);
  return report_outcome(settled, "running", `${instance.name} is running at ${instance.address_ip}.`);
}

/** Asks the API for the instance once a second until it reaches one of `states`, for up to 30 seconds. */
export async function wait_for_instance(instance_id: string, states: InstanceState[]): Promise<Instance | null> {
  for (let poll = 0; poll < MAX_POLLS; poll += 1) {
    await page.sleep(POLL_MILLISECONDS);
    let instance: Instance;
    try {
      instance = await api_client.instance_view(instance_id);
    } catch (error) {
      handle_refusal(error);
      return null;
    }
    replace_instance(instance);
    if (states.includes(instance.state)) {
      return instance;
    }
  }
  show_message("This is taking longer than usual. Reload the page to see where it stands.");
  return null;
}

/** The person presses "Stop" on an instance and confirms. */
export async function stop_instance(instance: Instance): Promise<Instance | null> {
  if (instance.state !== "running") {
    show_message("Only a running instance can be stopped.");
    return null;
  }
  const confirmed = await page.confirm(`Stop ${instance.name}? Anything running on it will be interrupted.`);
  if (!confirmed) {
    return null;
  }
  try {
    replace_instance(await api_client.instance_stop(instance.id));
  } catch (error) {
    handle_refusal(error);
    return null;
  }
  show_message(`Stopping ${instance.name}…`);
  const settled = await wait_for_instance(instance.id, ["stopped"]);
  return report_outcome(settled, "stopped", `${instance.name} is stopped.`);
}

/** The person presses "Start" on a stopped or failed instance. */
export async function start_instance(instance: Instance): Promise<Instance | null> {
  if (instance.state !== "stopped" && instance.state !== "failed") {
    show_message("Only a stopped instance can be started.");
    return null;
  }
  try {
    replace_instance(await api_client.instance_start(instance.id));
  } catch (error) {
    handle_refusal(error);
    return null;
  }
  show_message(`Starting ${instance.name}…`);
  const settled = await wait_for_instance(instance.id, ["running", "failed"]);
  return report_outcome(settled, "running", `${instance.name} is running.`);
}

/** The person presses "Delete" on an instance and confirms. */
export async function delete_instance(instance: Instance): Promise<boolean> {
  if (instance.state !== "stopped" && instance.state !== "failed") {
    show_message("Stop the instance first, then delete it.");
    return false;
  }
  const confirmed = await page.confirm(
    `Delete ${instance.name}? Its boot disk is deleted with it. Other disks are kept.`,
  );
  if (!confirmed) {
    return false;
  }
  try {
    await api_client.instance_delete(instance.id);
  } catch (error) {
    handle_refusal(error);
    return false;
  }
  show_message(`${instance.name} was deleted.`);
  const current = console_state.current_project;
  if (current !== null) {
    await switch_project(current.project.name);
  }
  return true;
}

/** The person submits the new-disk form. */
export async function submit_create_disk(name: string, size_gib: number): Promise<boolean> {
  const current = console_state.current_project;
  if (current === null) {
    return false;
  }
  const problem = name_problem(name);
  if (problem !== null) {
    show_message(problem);
    return false;
  }
  if (!Number.isInteger(size_gib) || size_gib < 1 || size_gib > 1000) {
    show_message("Choose a size of 1 to 1000 GiB.");
    return false;
  }
  try {
    await api_client.disk_create(current.project.name, name, size_gib);
  } catch (error) {
    handle_refusal(error);
    return false;
  }
  show_message(`The disk ${name} was created.`);
  return switch_project(current.project.name);
}

/** The person picks a disk to attach to an instance. */
export async function attach_disk(instance: Instance, disk: Disk): Promise<boolean> {
  if (instance.state !== "stopped") {
    show_message("Stop the instance first, then attach the disk.");
    return false;
  }
  try {
    const attached = await api_client.instance_disk_attach(instance.id, disk.id);
    console_state.disks = console_state.disks.map((each) => {
      if (each.id === attached.id) {
        return attached;
      }
      return each;
    });
  } catch (error) {
    handle_refusal(error);
    return false;
  }
  show_message(`${disk.name} is attached to ${instance.name}.`);
  return true;
}

/** The person presses "Delete" on a disk and confirms. */
export async function delete_disk(disk: Disk): Promise<boolean> {
  const current = console_state.current_project;
  if (current === null) {
    return false;
  }
  if (disk.attached_instance_id !== null) {
    show_message("This disk is attached to an instance. A boot disk is deleted with its instance.");
    return false;
  }
  try {
    await api_client.disk_delete(disk.id);
  } catch (error) {
    handle_refusal(error);
    return false;
  }
  show_message(`The disk ${disk.name} was deleted.`);
  return switch_project(current.project.name);
}

/** Sends one request with the session token, and turns any refusal into an ApiError. */
export async function api_request<Result>(method: string, path: string, body?: unknown): Promise<Result> {
  const headers: Record<string, string> = {};
  if (console_state.session_token !== null) {
    headers["Authorization"] = `Bearer ${console_state.session_token}`;
  }
  let payload: string | undefined;
  if (body !== undefined) {
    headers["Content-Type"] = "application/json";
    payload = JSON.stringify(body);
  }
  let response: Response;
  try {
    response = await fetch(`${API_ORIGIN}${path}`, { method, headers, body: payload });
  } catch {
    throw new ApiError(0, "Unreachable", "The API could not be reached.");
  }
  if (response.status === 204) {
    return undefined as Result;
  }
  const answer: unknown = await response.json().catch(() => null);
  if (!response.ok) {
    const refusal = (answer ?? {}) as { error_code?: string; message?: string };
    throw new ApiError(response.status, refusal.error_code ?? "Unknown", refusal.message ?? "");
  }
  return answer as Result;
}

