}

/// Refuses a request that would take a project past one of its quotas, naming the first one it would break.
pub fn check_quota(
    db: &Tables,
    project: &Project,
    cpus: u32,
    memory_gib: u32,
    disk_gib: u32,
) -> Result<(), ApiError> {
    let usage = db.project_usage(&project.id);
    let checks = [
        ("CPUs", cpus, project.quota_cpus.saturating_sub(usage.cpus)),
        ("GiB of memory", memory_gib, project.quota_memory_gib.saturating_sub(usage.memory_gib)),
        ("GiB of disk", disk_gib, project.quota_disk_gib.saturating_sub(usage.disk_gib)),
    ];
    for (resource, requested, available) in checks {
        if requested > available {
            return Err(ApiError::QuotaExceeded { resource: resource.to_string(), requested, available });
        }
    }
    Ok(())
}

/// Projects, instances and disks share one rule for names: lowercase letters, digits and dashes,
/// starting with a letter, not ending with a dash, at most 40 characters.
pub fn validate_name(name: &str) -> Result<(), ApiError> {
    let starts_with_letter = name.chars().next().is_some_and(|first| first.is_ascii_lowercase());
    let allowed = name.chars().all(|each| each.is_ascii_lowercase() || each.is_ascii_digit() || each == '-');
    if !starts_with_letter || !allowed || name.ends_with('-') || name.len() > MAX_NAME_LENGTH {
        return Err(ApiError::InvalidRequest(format!(
            "\"{name}\" is not a valid name: use lowercase letters, digits and dashes, starting with a letter"
        )));
    }
    Ok(())
}

/// Every new project starts with the same quota.
pub fn project_insert(&mut self, name: &str, description: &str) -> Project {
    let project = Project {
        id: self.next_id("project"),
        name: name.to_string(),
        description: description.to_string(),
        quota_cpus: DEFAULT_QUOTA_CPUS,
        quota_memory_gib: DEFAULT_QUOTA_MEMORY_GIB,
        quota_disk_gib: DEFAULT_QUOTA_DISK_GIB,
    };
    self.projects.push(project.clone());
    project
}

/// What the project holds against its quota. Instances count in every state, and disks attached or not.
pub fn project_usage(&self, project_id: &str) -> ProjectUsage {
    let mut usage = ProjectUsage::default();
    for instance in self.instances.iter().filter(|instance| instance.project_id == project_id) {
        usage.instances += 1;
        usage.cpus += instance.ncpus;
        usage.memory_gib += instance.memory_gib;
    }
    for disk in self.disks.iter().filter(|disk| disk.project_id == project_id) {
        usage.disks += 1;
        usage.disk_gib += disk.size_gib;
    }
    usage
}

/// Removes the project and every role on it.
pub fn project_delete(&mut self, project_id: &str) {
    self.role_assignments.retain(|each| each.project_id != project_id);
    self.projects.retain(|project| project.id != project_id);
}

/// Gives an instance that is creating or starting a place on the rack. It runs if the rack has
/// the CPUs and memory free, and fails if not.
pub fn place_instance(db: &mut Tables, instance: &Instance, now: u64) -> Option<Instance> {
    let (free_cpus, free_memory_gib) = db.rack_free_capacity();
    if instance.ncpus > free_cpus || instance.memory_gib > free_memory_gib {
        let reason = "The rack has no room for this instance right now.".to_string();
        return db.instance_set_state(&instance.id, InstanceState::Failed, Some(reason), now);
    }
    db.instance_set_state(&instance.id, InstanceState::Running, None, now)
}

/// The CPUs and memory no instance is using. Only running and stopping instances hold a place on the rack.
pub fn rack_free_capacity(&self) -> (u32, u32) {
    let mut used_cpus = 0;
    let mut used_memory_gib = 0;
    for instance in &self.instances {
        if matches!(instance.state, InstanceState::Running | InstanceState::Stopping) {
            used_cpus += instance.ncpus;
            used_memory_gib += instance.memory_gib;
        }
    }
    (
        self.rack.total_cpus.saturating_sub(used_cpus),
        self.rack.total_memory_gib.saturating_sub(used_memory_gib),
    )
}

/// Hands the first free address in the pool to an instance, or returns nothing when all are taken.
pub fn address_allocate(&mut self, instance_id: &str) -> Option<String> {
    let address = self.addresses.iter_mut().find(|address| address.instance_id.is_none())?;
    address.instance_id = Some(instance_id.to_string());
    Some(address.ip.clone())
}

/// Returns an instance's address to the pool.
pub fn address_release(&mut self, instance_id: &str) {
    for address in self.addresses.iter_mut() {
        if address.instance_id.as_deref() == Some(instance_id) {
            address.instance_id = None;
        }
    }
}

/// Holds the whole store for one piece of work, so its checks and writes cannot interleave with another's.
pub fn lock(&self) -> MutexGuard<'_, Tables> {
    self.tables.lock().unwrap_or_else(|poisoned| poisoned.into_inner())
}

export const console_state: ConsoleState = {
  session_token: null,
  user_name: null,
  projects: [],
  current_project: null,
  instances: [],
  disks: [],
  screen: "sign_in",
  message: null,
};

export function show_message(message: string | null): void {
  console_state.message = message;
}

export function replace_instance(instance: Instance): void {
  const others = console_state.instances.filter((each) => each.id !== instance.id);
  console_state.instances = [...others, instance].sort((a, b) => a.name.localeCompare(b.name));
}

/** What the console asks of the page around it. Tests and other hosts can replace these. */
export const page = {
  confirm: async (question: string): Promise<boolean> => globalThis.confirm(question),
  sleep: (milliseconds: number): Promise<void> => new Promise((done) => setTimeout(done, milliseconds)),
  remember: (key: string, value: string | null): void => {
    if (value === null) {
      globalThis.localStorage.removeItem(key);
    } else {
      globalThis.localStorage.setItem(key, value);
    }
  },
  recall: (key: string): string | null => globalThis.localStorage.getItem(key),
};

/// A person who can sign in to the console.
#[derive(Clone, Debug)]
pub struct User {
    pub id: String,
    /// What the person types to sign in. Unique.
    pub name: String,
    pub password_digest: u64,
    /// Wrong passwords in a row since the last good sign-in.
    pub failed_logins: u32,
    /// Sign-in is refused until this time, after too many wrong passwords.
    pub locked_until: Option<u64>,
}

/// One signed-in browser. The console sends its token with every request.
#[derive(Clone, Debug)]
pub struct Session {
    pub token: String,
    pub user_id: String,
    pub expires_at: u64,
}

/// What a person may do in a project. Each role includes the ones before it.
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "snake_case")]
pub enum ProjectRole {
    /// May look at the project and what it holds.
    Viewer,
    /// May also create, start, stop and delete instances and disks.
    Collaborator,
    /// May also change who has a role, and delete the project.
    Admin,
}

/// The role one person has on one project. A person with no role cannot see the project at all.
#[derive(Clone, Debug)]
pub struct RoleAssignment {
    pub project_id: String,
    pub user_id: String,
    pub role: ProjectRole,
}

/// A group of instances and disks, with a quota they share.
#[derive(Clone, Debug, Serialize, JsonSchema)]
pub struct Project {
    pub id: String,
    /// Unique across the rack. The console addresses a project by its name.
    pub name: String,
    pub description: String,
    /// The most CPUs its instances may hold together, running or not.
    pub quota_cpus: u32,
    pub quota_memory_gib: u32,
    /// The most storage its disks may hold together, attached or not.
    pub quota_disk_gib: u32,
}

/// Where an instance is in its life.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "snake_case")]
pub enum InstanceState {
    /// Recorded, and waiting for a place on the rack for the first time.
    Creating,
    /// Asked to start again, and waiting for a place on the rack.
    Starting,
    /// Placed on the rack and using its CPUs and memory.
    Running,
    /// Asked to stop. It still holds its place on the rack.
    Stopping,
    /// Off. It keeps its disks, address and quota, and uses no rack capacity.
    Stopped,
    /// The rack had no room when it was created or started.
    Failed,
}

/// A virtual machine in a project.
#[derive(Clone, Debug, Serialize, JsonSchema)]
pub struct Instance {
    pub id: String,
    pub project_id: String,
    /// Unique within its project.
    pub name: String,
    pub ncpus: u32,
    pub memory_gib: u32,
    pub state: InstanceState,
    /// When it entered its state. Creating, starting and stopping finish a few seconds after this.
    pub state_changed_at: u64,
    /// The disk it starts from. Created with the instance and deleted with it.
    pub boot_disk_id: String,
    /// Held from creation until the instance is deleted.
    pub address_ip: String,
    /// Why it failed, in words for the person. Empty unless the state is failed.
    pub failure_reason: Option<String>,
}

/// Storage in a project. A disk is attached to one instance or to none.
#[derive(Clone, Debug, Serialize, JsonSchema)]
pub struct Disk {
    pub id: String,
    pub project_id: String,
    /// Unique within its project.
    pub name: String,
    pub size_gib: u32,
    pub attached_instance_id: Option<String>,
    /// A boot disk lives and dies with its instance and cannot be deleted on its own.
    pub is_boot_disk: bool,
}

/// One address from the rack's pool. Every project draws from the same pool.
#[derive(Clone, Debug)]
pub struct Address {
    pub ip: String,
    /// The instance holding it, or nobody.
    pub instance_id: Option<String>,
}

/// The hardware every project shares. Running instances use its CPUs and memory.
#[derive(Clone, Debug)]
pub struct Rack {
    pub total_cpus: u32,
    pub total_memory_gib: u32,
}

/// How much of its quota a project is using.
#[derive(Clone, Debug, Default, Serialize, JsonSchema)]
pub struct ProjectUsage {
    pub instances: usize,
    pub disks: usize,
    pub cpus: u32,
    pub memory_gib: u32,
    pub disk_gib: u32,
}

pub fn disk_by_id(&self, disk_id: &str) -> Option<Disk> {
    self.disks.iter().find(|disk| disk.id == disk_id).cloned()
}

pub fn disk_by_name(&self, project_id: &str, name: &str) -> Option<Disk> {
    self.disks.iter().find(|disk| disk.project_id == project_id && disk.name == name).cloned()
}

/// The disks of a project, by name.
pub fn disks_in_project(&self, project_id: &str) -> Vec<Disk> {
    let mut disks: Vec<Disk> =
        self.disks.iter().filter(|disk| disk.project_id == project_id).cloned().collect();
    disks.sort_by(|a, b| a.name.cmp(&b.name));
    disks
}

/// Attaches the disk to an instance, or to none.
pub fn disk_set_attachment(&mut self, disk_id: &str, instance_id: Option<&str>) -> Option<Disk> {
    let disk = self.disks.iter_mut().find(|disk| disk.id == disk_id)?;
    disk.attached_instance_id = instance_id.map(str::to_string);
    Some(disk.clone())
}

pub fn disk_delete(&mut self, disk_id: &str) {
    self.disks.retain(|disk| disk.id != disk_id);
}

pub fn instance_insert(&mut self, instance: Instance) {
    self.instances.push(instance);
}

pub fn instance_by_id(&self, instance_id: &str) -> Option<Instance> {
    self.instances.iter().find(|instance| instance.id == instance_id).cloned()
}

pub fn instance_by_name(&self, project_id: &str, name: &str) -> Option<Instance> {
    self.instances
        .iter()
        .find(|instance| instance.project_id == project_id && instance.name == name)
        .cloned()
}

/// The instances of a project, by name.
pub fn instances_in_project(&self, project_id: &str) -> Vec<Instance> {
    let mut instances: Vec<Instance> =
        self.instances.iter().filter(|instance| instance.project_id == project_id).cloned().collect();
    instances.sort_by(|a, b| a.name.cmp(&b.name));
    instances
}

pub fn instance_delete(&mut self, instance_id: &str) {
    self.instances.retain(|instance| instance.id != instance_id);
}

pub fn project_by_name(&self, name: &str) -> Option<Project> {
    self.projects.iter().find(|project| project.name == name).cloned()
}

pub fn project_by_id(&self, project_id: &str) -> Option<Project> {
    self.projects.iter().find(|project| project.id == project_id).cloned()
}

/// The projects a person has any role on, by name.
pub fn projects_for_user(&self, user_id: &str) -> Vec<Project> {
    let mut projects: Vec<Project> = self
        .projects
        .iter()
        .filter(|project| self.role_of(&project.id, user_id).is_some())
        .cloned()
        .collect();
    projects.sort_by(|a, b| a.name.cmp(&b.name));
    projects
}

/// A stand-in for a real password hash, so the example needs no extra crate. Do not use it for real passwords.
pub fn password_digest(user_name: &str, password: &str) -> u64 {
    let mut hasher = DefaultHasher::new();
    ("oxide-lite", user_name, password).hash(&mut hasher);
    hasher.finish()
}

pub fn user_by_name(&self, name: &str) -> Option<User> {
    self.users.iter().find(|user| user.name == name).cloned()
}

pub fn user_by_id(&self, user_id: &str) -> Option<User> {
    self.users.iter().find(|user| user.id == user_id).cloned()
}

/// Counts one more wrong password, and returns how many there have been in a row.
pub fn user_record_failed_login(&mut self, user_id: &str) -> u32 {
    let Some(user) = self.users.iter_mut().find(|user| user.id == user_id) else {
        return 0;
    };
    user.failed_logins += 1;
    user.failed_logins
}

pub fn session_by_token(&self, token: &str) -> Option<Session> {
    self.sessions.iter().find(|session| session.token == token).cloned()
}

pub fn session_delete(&mut self, token: &str) {
    self.sessions.retain(|session| session.token != token);
}

pub fn role_of(&self, project_id: &str, user_id: &str) -> Option<ProjectRole> {
    self.role_assignments
        .iter()
        .find(|each| each.project_id == project_id && each.user_id == user_id)
        .map(|each| each.role)
}

pub fn admin_count(&self, project_id: &str) -> usize {
    self.role_assignments
        .iter()
        .filter(|each| each.project_id == project_id && each.role == ProjectRole::Admin)
        .count()
}
